def is_pending(job, current_time):
    return job.release_time <= current_time and not job.is_completed

def is_ready(job, current_time):
    if not is_pending(job, current_time):
        return False
    if job.predecessor is None:
        return True
    else:
        return job.predecessor.is_completed

def get_ready_time(job_k_j):
    release_time = job_k_j.release_time
    predecessor_completion_time = 0
    if job_k_j.job_index > 1:
        predecessor_completion_time = job_k_j.predecessor.completion_time
    return max(release_time, predecessor_completion_time)

def get_priority_pending_tasks(current_time, job_k_j, all_tasks):
    tau_p = set()
    for task_a in all_tasks:
        for job_a_b in task_a.pending_jobs_at(current_time):
            if job_a_b.priority >= job_k_j.priority:
                tau_p.add(task_a)
                break # No need to check other jobs of task_a
    return tau_p

def is_interval_busy(start_time, end_time, tau_p_func, num_processors, task_execution_func):
    for t in range(start_time, end_time):
        pending_high_priority_tasks = tau_p_func(t)
        num_pending_high_priority = len(pending_high_priority_tasks)
        executing_tasks = task_execution_func(t)
        num_executing = len(executing_tasks)

        if num_pending_high_priority < num_processors and num_executing < num_pending_high_priority:
            # This condition implies that the pending high-priority tasks are occupying all processors
            pass # Processor is busy
        elif num_pending_high_priority >= num_processors:
            # More high-priority tasks pending than processors, so all processors must be busy
            pass # Processor is busy
        else:
            # If neither of the above conditions are met, it means a processor is idle
            return False
    return True

def check_theorem_1(task_set, m):
    for task_k in task_set:
        # Determine the range of delta_k to check (from Lemma 1 up to delta_max from Def 8)
        min_delta_k = get_lemma_1_bound(task_k, task_set)
        max_delta_k = calculate_delta_max(task_set, m, task_k) # From Def 8

        # Iterate through relevant delta_k values (e.g., critical points where DBF changes)
        # For simplicity, let's assume we check a sufficient set of delta_k values.
        for delta_k in generate_critical_delta_k_values(min_delta_k, max_delta_k, task_set):
            M_star_Tk = calculate_M_star(task_k, delta_k, task_set, m) # From Formula (5)
            rhs = m * (delta_k + task_k.Theta + 1 - task_k.e)
            if M_star_Tk >= rhs:
                return False # Schedulability failed for task_k at this delta_k

    return True # Schedulable if all checks pass

def get_I_NC_bound(task_i, task_k, delta_k, theta_k, all_tasks):
    # This function implements the bounds from Lemma 5.
    if task_i == task_k:
        # Case i = k
        bound1 = demand_bound_function(task_i, delta_k) # Using Formula (6)
        bound2 = delta_k + task_k.Theta + 1 - task_k.e
        return min(bound1, bound2)
    else:
        # Case i != k
        if delta_k >= task_k.D:
            # Subcase: delta_k >= D_k
            bound1 = demand_bound_function(task_i, delta_k) - task_k.e
            bound2 = max(delta_k - task_k.D, delta_k - task_k.p + task_k.Theta)
            return min(bound1, bound2)
        else:
            # Subcase: delta_k < D_k
            return 0

def get_I_CH_bound(task_i, task_k, delta_k, theta_k, all_tasks):
    # This function implements the bounds from Lemma 6.
    if task_i == task_k:
        # Case i = k
        bound1 = modified_demand_bound_function(task_i, delta_k) # Using Formula (7)
        bound2 = delta_k + task_k.Theta + 1 - task_k.e
        return min(bound1, bound2)
    else:
        # Case i != k
        bound1 = modified_demand_bound_function(task_i, delta_k) - task_k.e
        bound2 = max(delta_k - task_k.D, delta_k - task_k.p + task_k.Theta)
        return min(bound1, bound2)

def calculate_M_Tk(task_k, delta_k, tau_CH, tau_CL, tau_NC, task_set):
    total_demand = 0
    for task_i in task_set:
        if task_i in tau_CH:
            total_demand += get_I_CH_bound(task_i, task_k, delta_k, task_k.Theta, task_set) # Using Lemma 6
        elif task_i in tau_CL:
            total_demand += get_I_CL_bound(task_i, task_k, delta_k, task_k.Theta, task_set) # Using Lemma 4
        elif task_i in tau_NC:
            total_demand += get_I_NC_bound(task_i, task_k, delta_k, task_k.Theta, task_set) # Using Lemma 5
    return total_demand

def calculate_M_Tk_for_partition(task_k, delta_k, tau_CH, tau_CL, tau_NC, task_set):
    total_demand = 0
    for task_i in tau_CH:
        total_demand += get_I_CH_bound(task_i, task_k, delta_k, task_k.Theta, task_set)
    for task_i in tau_CL:
        total_demand += get_I_CL_bound(task_i, task_k, delta_k, task_k.Theta, task_set)
    for task_i in tau_NC:
        total_demand += get_I_NC_bound(task_i, task_k, delta_k, task_k.Theta, task_set)
    return total_demand

def is_valid_partition(tau_CH, tau_CL, tau_NC, task_k, delta_k, D_k, m, all_tasks):
    # Check set disjointness and coverage
    all_assigned = tau_CH.union(tau_CL).union(tau_NC)
    if not all_assigned.issuperset(all_tasks) or not all_assigned.issubset(all_tasks):
        return False
    if not tau_CH.isdisjoint(tau_CL) or not tau_CH.isdisjoint(tau_NC) or not tau_CL.isdisjoint(tau_NC):
        return False

    # Check T_k constraint
    if task_k not in tau_CL:
        return False

    # Check delta_k < D_k constraint
    if delta_k < D_k and task_k not in tau_CH:
        return False

    # Check size constraints
    if len(tau_CH) > m - 1:
        return False
    if len(tau_CH.union(tau_CL)) > m:
        return False

    return True

